<template><MerchantShell title="门店订单物流" :manager="manager"><template v-if="tracking"><view class="merchant-card"><text class="merchant-subtitle">{{ tracking.order.order_id }}</text><view>{{ tracking.order.delivery_name }}</view><text class="merchant-link" @tap="copy(tracking.order.delivery_id)">{{ tracking.order.delivery_id }} · 复制运单号</text></view><view v-for="pack in tracking.packages" :key="pack.orderId" class="merchant-card"><text class="merchant-subtitle">{{ pack.orderId }}</text><view class="merchant-row"><text>{{ pack.expressName }} {{ pack.expressNo }}</text><text class="merchant-status">{{ stateLabel(pack.trackingState) }}</text></view><text class="merchant-note">{{ sourceLabel(pack.trackingSource) }}<text v-if="pack.lastUpdatedAt"> · {{ merchantDate(pack.lastUpdatedAt) }}</text></text><view v-if="pack.message" class="merchant-warning">{{ pack.message }}</view><view v-for="(trace,index) in displayed(pack)" :key="`${trace.time}:${index}`" class="merchant-stack" style="padding:20rpx 0;border-bottom:1rpx solid #e4eae6"><text>{{ trace.content || trace.status }}</text><text class="merchant-note">{{ trace.time }}</text></view><text v-if="!pack.traces.length" class="merchant-note">暂无可确认的快递轨迹</text><button v-if="pack.traces.length>3" class="merchant-full-button" @tap="expanded[pack.orderId]=!expanded[pack.orderId]">{{ expanded[pack.orderId] ? '收起轨迹' : '展开全部轨迹' }}</button></view></template></MerchantShell></template>
<script setup lang="ts">
import { ref } from 'vue';import MerchantShell from '@/components/merchantOrders/MerchantShell.vue';import { useMerchantOrders } from '@/composables/useMerchantOrders';import { isMerchantDetail,isMerchantExpress,merchantOrderId,merchantDate } from '@/utils/merchantOrders';import type { MerchantExpressResult,MerchantTrackingPackage } from '@/types/merchantOrders';
const tracking=ref<MerchantExpressResult|null>(null),expanded=ref<Record<string,boolean>>({});let orderId='';const manager=useMerchantOrders({query(query){orderId=query.orderId||query.id||'';},clear(){tracking.value=null;expanded.value={};},async load(controller){const valid=controller.fence();if(!merchantOrderId(orderId))throw Error('订单编号无效');const order=await controller.read(`detail/${encodeURIComponent(orderId)}`,isMerchantDetail);if(!valid())return;if(!order.data.actions.tracking.available)throw Error(order.data.actions.tracking.reason||'当前订单没有可查询物流');const response=await controller.read(`express/${encodeURIComponent(orderId)}`,isMerchantExpress);if(!valid())return;if(response.data.order.order_id!==orderId||response.data.orderId!==orderId)throw Error('物流订单响应不匹配');tracking.value=response.data;}});
function stateLabel(value:string){return ({pending:'待查询',in_transit:'运输中',delivered:'已签收',exception:'物流异常',not_configured:'暂未开放查询',temporarily_unavailable:'查询暂不可用'} as Record<string,string>)[value]||'待核对';}function sourceLabel(value:string){return ({merchant:'商家物流信息',carrier:'快递轨迹',cache:'最近查询记录'} as Record<string,string>)[value]||'物流信息';}function displayed(pack:MerchantTrackingPackage){return expanded.value[pack.orderId]?pack.traces:pack.traces.slice(0,3);}function copy(value:string){if(manager.current()&&value)uni.setClipboardData({data:value});}
</script>
